# Parse results
molecules = sql_results_0
nitrogen_molecules = {row['molecule_id'] for row in sql_results_1}
examinations = sql_results_2

# Calculate p1: proportion of nitrogen-containing molecules that are carcinogenic
nitrogen_carcinogenic = 0
nitrogen_total = 0

for mol in molecules:
    if mol['molecule_id'] in nitrogen_molecules:
        nitrogen_total += 1
        if mol['carcinogenicity'] == 1 or mol['carcinogenicity'] == True or str(mol['carcinogenicity']).lower() in ['true', '1', 'yes']:
            nitrogen_carcinogenic += 1

if nitrogen_total > 0:
    p1 = nitrogen_carcinogenic / nitrogen_total
else:
    p1 = 0.0

# Calculate p2: proportion of examined patients with confirmed thrombosis (Thrombosis >= 1)
thrombosis_confirmed = 0
total_patients = 0

for exam in examinations:
    total_patients += 1
    if exam['Thrombosis'] is not None and int(exam['Thrombosis']) >= 1:
        thrombosis_confirmed += 1

if total_patients > 0:
    p2 = thrombosis_confirmed / total_patients
else:
    p2 = 0.0

# Perform two-sided pooled two-proportion z-test
n1 = nitrogen_total
n2 = total_patients

if n1 > 0 and n2 > 0:
    # Pooled proportion
    p_pool = (nitrogen_carcinogenic + thrombosis_confirmed) / (n1 + n2)

    # Standard error
    se = math.sqrt(p_pool * (1 - p_pool) * (1/n1 + 1/n2))

    # Z-statistic
    if se > 0:
        z = (p1 - p2) / se
    else:
        z = 0.0
else:
    z = 0.0

result = {
    "p1": float(p1),
    "p2": float(p2),
    "z": float(z)
}

print(json.dumps(result))

